import React, { useState } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import productsData from '../data/productsData';
import AuthModal from '../components/AuthModal';
import './ProductDetails.css';

// ─── Star Rating ──────────────────────────────────────────────────────────────
function StarRating({ value, onChange, size = 22, readonly = false }) {
  const [hovered, setHovered] = useState(0);
  return (
    <div style={{ display: 'flex', gap: 2 }}>
      {[1, 2, 3, 4, 5].map((i) => (
        <span
          key={i}
          onClick={() => !readonly && onChange && onChange(i)}
          onMouseEnter={() => !readonly && setHovered(i)}
          onMouseLeave={() => !readonly && setHovered(0)}
          style={{
            fontSize: size,
            cursor: readonly ? 'default' : 'pointer',
            color: i <= (hovered || value) ? '#f59e0b' : '#d1d5db',
            transition: 'color 0.15s',
            lineHeight: 1,
            userSelect: 'none',
          }}
        >★</span>
      ))}
    </div>
  );
}

// ─── Single Review Item ───────────────────────────────────────────────────────
function ReviewItem({ review }) {
  return (
    <div style={{
      background: '#f9fafb', borderRadius: 10,
      padding: '10px 14px', marginBottom: 8,
      borderLeft: '3px solid #ec4899',
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
        <div style={{
          width: 32, height: 32, borderRadius: '50%',
          background: 'linear-gradient(135deg, #ec4899, #f43f5e)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontWeight: 700, fontSize: 13, color: 'white', flexShrink: 0,
        }}>
          {review.name.charAt(0).toUpperCase()}
        </div>
        <div>
          <p style={{ fontWeight: 600, fontSize: 13, margin: 0, color: '#111827' }}>{review.name}</p>
          <StarRating value={review.stars} readonly size={13} />
        </div>
        <span style={{ marginLeft: 'auto', fontSize: 11, color: '#9ca3af' }}>{review.date}</span>
      </div>
      <p style={{ margin: 0, fontSize: 13, color: '#374151', lineHeight: 1.5 }}>{review.text}</p>
    </div>
  );
}

// ─── Ratings & Reviews Section ────────────────────────────────────────────────
function RatingsReviews({ productId }) {
  const storageKey = `reviews_${productId}`;

  const [reviews, setReviews] = useState(() => {
    try {
      const saved = localStorage.getItem(storageKey);
      return saved ? JSON.parse(saved) : [];
    } catch { return []; }
  });

  const [userRating, setUserRating] = useState(() => {
    try {
      return parseInt(localStorage.getItem(`myrating_${productId}`)) || 0;
    } catch { return 0; }
  });

  const [showReviews, setShowReviews] = useState(false);
  const [showForm, setShowForm]       = useState(false);
  const [newName, setNewName]         = useState('');
  const [newStars, setNewStars]       = useState(0);
  const [newText, setNewText]         = useState('');
  const [error, setError]             = useState('');

  const avgRating = reviews.length > 0
    ? (reviews.reduce((s, r) => s + r.stars, 0) / reviews.length).toFixed(1)
    : null;

  function handleRatingChange(val) {
    setUserRating(val);
    localStorage.setItem(`myrating_${productId}`, val);
  }

  function handleSubmit() {
    if (!newName.trim()) { setError('Naam likhna zaroori hai!'); return; }
    if (newStars === 0)  { setError('Star rating do!'); return; }
    if (!newText.trim()) { setError('Review likhna zaroori hai!'); return; }
    setError('');

    const review = {
      id: Date.now(),
      name: newName.trim(),
      stars: newStars,
      text: newText.trim(),
      date: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
    };

    const updated = [review, ...reviews];
    setReviews(updated);
    localStorage.setItem(storageKey, JSON.stringify(updated));
    setNewName(''); setNewStars(0); setNewText('');
    setShowForm(false); setShowReviews(true);
  }

  return (
    <div style={{
      background: 'white', border: '2px solid #fde68a',
      borderRadius: 16, padding: '24px', marginBottom: 24,
    }}>
      {/* Header */}
      <h3 style={{ fontSize: 18, fontWeight: 700, color: '#0f172a', marginBottom: 16, display: 'flex', alignItems: 'center', gap: 8 }}>
        ⭐ Ratings & Reviews
      </h3>

      {/* Average + Apni Rating */}
      <div style={{ display: 'flex', gap: 24, alignItems: 'center', flexWrap: 'wrap', marginBottom: 16 }}>
        {avgRating ? (
          <div style={{ textAlign: 'center' }}>
            <div style={{ fontSize: 40, fontWeight: 800, color: '#f59e0b', lineHeight: 1 }}>{avgRating}</div>
            <StarRating value={Math.round(parseFloat(avgRating))} readonly size={16} />
            <p style={{ fontSize: 12, color: '#6b7280', margin: '4px 0 0' }}>{reviews.length} review{reviews.length !== 1 ? 's' : ''}</p>
          </div>
        ) : (
          <p style={{ fontSize: 13, color: '#9ca3af', fontStyle: 'italic' }}>Abhi koi review nahi</p>
        )}

        <div style={{ borderLeft: '1px solid #e5e7eb', paddingLeft: 24 }}>
          <p style={{ margin: '0 0 6px', fontSize: 13, color: '#6b7280' }}>Apni rating do:</p>
          <StarRating value={userRating} onChange={handleRatingChange} size={28} />
          {userRating > 0 && (
            <p style={{ fontSize: 12, color: '#f59e0b', margin: '4px 0 0', fontWeight: 600 }}>
              Tumne diya: {userRating}/5 ⭐
            </p>
          )}
        </div>
      </div>

      {/* Action Buttons */}
      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 12 }}>
        {reviews.length > 0 && (
          <button
            onClick={() => setShowReviews(v => !v)}
            style={{
              background: showReviews ? '#fef3c7' : '#f9fafb',
              border: '1px solid #e5e7eb', borderRadius: 8,
              padding: '8px 16px', fontSize: 13,
              cursor: 'pointer', color: '#374151', fontWeight: 500,
            }}
          >
            {showReviews ? '▲ Reviews chhupao' : `▼ ${reviews.length} Review${reviews.length > 1 ? 's' : ''} dekho`}
          </button>
        )}
        <button
          onClick={() => setShowForm(v => !v)}
          style={{
            background: showForm ? '#fef3c7' : 'linear-gradient(135deg, #ec4899, #f43f5e)',
            border: 'none', borderRadius: 8,
            padding: '8px 16px', fontSize: 13,
            cursor: 'pointer',
            color: showForm ? '#374151' : 'white',
            fontWeight: 600,
            boxShadow: showForm ? 'none' : '0 4px 12px rgba(236,72,153,0.3)',
          }}
        >
          {showForm ? '✕ Cancel' : '✍️ Review likho'}
        </button>
      </div>

      {/* Reviews List */}
      {showReviews && reviews.length > 0 && (
        <div style={{ marginBottom: 12 }}>
          {reviews.map(r => <ReviewItem key={r.id} review={r} />)}
        </div>
      )}

      {/* Add Review Form */}
      {showForm && (
        <div style={{
          background: '#fffbeb', border: '1px solid #fde68a',
          borderRadius: 12, padding: '16px',
        }}>
          <p style={{ margin: '0 0 12px', fontWeight: 700, fontSize: 15, color: '#92400e' }}>
            Apna review likho
          </p>

          <input
            type="text"
            placeholder="Aapka naam *"
            value={newName}
            onChange={e => setNewName(e.target.value)}
            style={{
              width: '100%', padding: '9px 12px',
              border: '1px solid #fcd34d', borderRadius: 8,
              fontSize: 13, marginBottom: 10,
              outline: 'none', background: '#fff', boxSizing: 'border-box',
            }}
          />

          <div style={{ marginBottom: 10 }}>
            <p style={{ margin: '0 0 6px', fontSize: 12, color: '#92400e', fontWeight: 500 }}>Rating do *</p>
            <StarRating value={newStars} onChange={setNewStars} size={26} />
          </div>

          <textarea
            placeholder="Is product ke baare mein apna experience likho..."
            value={newText}
            onChange={e => setNewText(e.target.value)}
            rows={3}
            style={{
              width: '100%', padding: '9px 12px',
              border: '1px solid #fcd34d', borderRadius: 8,
              fontSize: 13, marginBottom: 10,
              resize: 'vertical', outline: 'none',
              background: '#fff', fontFamily: 'inherit', boxSizing: 'border-box',
            }}
          />

          {error && (
            <p style={{ margin: '0 0 10px', fontSize: 13, color: '#dc2626', fontWeight: 500 }}>
              ⚠️ {error}
            </p>
          )}

          <button
            onClick={handleSubmit}
            style={{
              width: '100%', padding: '12px',
              background: 'linear-gradient(135deg, #ec4899, #f43f5e)',
              color: 'white', border: 'none', borderRadius: 8,
              fontSize: 15, fontWeight: 700, cursor: 'pointer',
              boxShadow: '0 4px 12px rgba(236,72,153,0.3)',
            }}
          >
            Post Review →
          </button>
        </div>
      )}
    </div>
  );
}

// ─── Main ProductDetails Component ───────────────────────────────────────────
const ProductDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [isFavorite, setIsFavorite] = useState(false);
  const [showAuth, setShowAuth] = useState(false);
  const [currentUser, setCurrentUser] = useState(() => {
    const saved = localStorage.getItem('campusUser');
    return saved ? JSON.parse(saved) : null;
  });
  const [buySuccess, setBuySuccess] = useState(false);

  const postedItems = JSON.parse(localStorage.getItem('campusPostedItems') || '[]');
  const allProducts = [...productsData, ...postedItems];
  const product = allProducts.find((p) => p.id === parseInt(id));

  const relatedProducts = product
    ? allProducts.filter((p) => p.category === product.category && p.id !== product.id).slice(0, 3)
    : [];

  const handleBuy = () => {
    if (currentUser) {
      const orders = JSON.parse(localStorage.getItem('campusOrders') || '[]');
      const newOrder = {
        orderId: Date.now(),
        productId: product.id,
        title: product.title,
        price: product.price,
        category: product.category,
        image: product.image,
        seller: product.name,
        sellerContact: product.contact,
        orderedAt: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
      };
      orders.push(newOrder);
      localStorage.setItem('campusOrders', JSON.stringify(orders));
      setBuySuccess(true);
      setTimeout(() => setBuySuccess(false), 4000);
    } else {
      setShowAuth(true);
    }
  };

  const handleAuthSuccess = (user) => {
    setCurrentUser(user);
    const orders = JSON.parse(localStorage.getItem('campusOrders') || '[]');
    const newOrder = {
      orderId: Date.now(),
      productId: product.id,
      title: product.title,
      price: product.price,
      category: product.category,
      image: product.image,
      seller: product.name,
      sellerContact: product.contact,
      orderedAt: new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }),
    };
    orders.push(newOrder);
    localStorage.setItem('campusOrders', JSON.stringify(orders));
    setBuySuccess(true);
    setTimeout(() => setBuySuccess(false), 4000);
  };

  const handleLogout = () => {
    localStorage.removeItem('campusUser');
    setCurrentUser(null);
  };

  if (!product) {
    return (
      <main className="page-shell">
        <section style={{ textAlign: 'center', padding: '60px 20px' }}>
          <h2>Product not found</h2>
          <p>Sorry, we couldn't find the product you're looking for.</p>
          <button onClick={() => navigate('/')} className="gradient-btn" style={{ marginTop: '20px' }}>
            ← Back to Browse
          </button>
        </section>
      </main>
    );
  }

  return (
    <main className="page-shell product-details-page">
      <AuthModal isOpen={showAuth} onClose={() => setShowAuth(false)} onSuccess={handleAuthSuccess} />

      <button type="button" className="back-button" onClick={() => navigate(-1)}
        style={{
          background: 'rgba(15, 23, 42, 0.08)', border: 'none', padding: '10px 16px',
          borderRadius: '8px', cursor: 'pointer', fontSize: '14px', fontWeight: '600',
          color: '#0f172a', marginBottom: '24px', transition: 'all 0.3s ease',
          display: 'inline-flex', alignItems: 'center', gap: '8px'
        }}
        onMouseEnter={(e) => (e.currentTarget.style.background = 'rgba(15, 23, 42, 0.15)')}
        onMouseLeave={(e) => (e.currentTarget.style.background = 'rgba(15, 23, 42, 0.08)')}
