      <section className="product-details-container">
        <div className="product-image-section">
          <div className="product-main-image" style={{
            width: '100%', maxWidth: '500px', height: '500px',
            borderRadius: '16px', boxShadow: '0 20px 60px rgba(15, 23, 42, 0.15)',
            position: 'relative', overflow: 'hidden',
            background: 'linear-gradient(135deg, #e0fdf4, #ccfbf1)'
          }}>
            <img
              src={product.image || 'https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?auto=format&fit=crop&w=800&q=80'}
              alt={product.title}
              style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
